 1	import java.util.Arrays;
 2	
 3	public final class CountingSortTest {
 4	
 5	    private CountingSortTest() {
 6	    }
 7	
 8	    public static void main(String[] args) {
 9	        assertArrayEquals(
10	            new int[] {},
11	            CountingSort.sortedCopy(new int[] {})
12	        );
13	        assertArrayEquals(
14	            new int[] {-4, -1, 0, 0, 2, 2, 3, 3, 3, 5},
15	            CountingSort.sortedCopy(new int[] {2, 5, 3, 0, 2, 3, 0, 3, -4, -1})
16	        );
17	
18	        int[] output = new int[4];
19	        CountingSort.copyInto(new int[] {3, -1, 3, 0}, output);
20	        assertArrayEquals(new int[] {-1, 0, 3, 3}, output);
21	
22	        int[] values = {3, -1, 3, 0};
23	        CountingSort.sortInPlace(values);
24	        assertArrayEquals(new int[] {-1, 0, 3, 3}, values);
25	
26	        assertThrows(
27	            IllegalArgumentException.class,
28	            () -> CountingSort.copyInto(new int[] {1, 2}, new int[1])
29	        );
30	        assertThrows(
31	            NullPointerException.class,
32	            () -> CountingSort.sortedCopy(null)
33	        );
34	    }
35	
36	    private static void assertArrayEquals(int[] expected, int[] actual) {
37	        if (!Arrays.equals(expected, actual)) {
38	            throw new AssertionError(
39	                "Expected " + Arrays.toString(expected)
40	                    + " but was " + Arrays.toString(actual)
41	            );
42	        }
43	    }
44	
45	    private static void assertThrows(
46	        Class<? extends Throwable> expectedType,
47	        ThrowingRunnable action
48	    ) {
49	        try {
50	            action.run();
51	        } catch (Throwable throwable) {
52	            if (expectedType.isInstance(throwable)) {
53	                return;
54	            }
55	
56	            throw new AssertionError(
57	                "Expected " + expectedType.getSimpleName()
58	                    + " but caught " + throwable.getClass().getSimpleName(),
59	                throwable
60	            );
61	        }
62	
63	        throw new AssertionError(
64	            "Expected " + expectedType.getSimpleName() + " to be thrown."
65	        );
66	    }
67	
68	    @FunctionalInterface
69	    private interface ThrowingRunnable {
70	        void run();
71	    }
72	}

  1	import java.util.Objects;
  2	
  3	/**
  4	 * Stable counting sort for integer arrays.
  5	 */
  6	public final class CountingSort {
  7	
  8	    private CountingSort() {
  9	    }
 10	
 11	    /**
 12	     * Legacy wrapper retained for compatibility.
 13	     */
 14	    public static int[] countSort(int[] values) {
 15	        return sortedCopy(values);
 16	    }
 17	
 18	    /**
 19	     * Legacy wrapper retained for compatibility.
 20	     */
 21	    public static int[] sort(int[] values) {
 22	        return sortedCopy(values);
 23	    }
 24	
 25	    /**
 26	     * Returns a sorted copy of {@code values}.
 27	     */
 28	    public static int[] sortedCopy(int[] values) {
 29	        Objects.requireNonNull(values, "values");
 30	        int[] sortedValues = new int[values.length];
 31	        copyInto(values, sortedValues);
 32	        return sortedValues;
 33	    }
 34	
 35	    /**
 36	     * Writes the sorted contents of {@code input} into {@code output}.
 37	     */
 38	    public static void copyInto(int[] input, int[] output) {
 39	        Objects.requireNonNull(input, "input");
 40	        Objects.requireNonNull(output, "output");
 41	        requireSameLength(input, output);
 42	
 43	        if (input.length == 0) {
 44	            return;
 45	        }
 46	
 47	        int[] source = aliasSafeInput(input, output);
 48	        CountingTable countingTable = CountingTable.from(source);
 49	        writeSortedValues(source, output, countingTable);
 50	    }
 51	
 52	    /**
 53	     * Sorts {@code values} in place.
 54	     */
 55	    public static void sortInPlace(int[] values) {
 56	        Objects.requireNonNull(values, "values");
 57	
 58	        if (values.length == 0) {
 59	            return;
 60	        }
 61	
 62	        copyInto(values, values);
 63	    }
 64	
 65	    private static int[] aliasSafeInput(int[] input, int[] output) {
 66	        return input == output ? input.clone() : input;
 67	    }
 68	
 69	    private static void requireSameLength(int[] input, int[] output) {
 70	        if (input.length != output.length) {
 71	            throw new IllegalArgumentException(
 72	                "Input and output arrays must have the same length."
 73	            );
 74	        }
 75	    }
 76	
 77	    private static Range findRange(int[] values) {
 78	        int minValue = values[0];
 79	        int maxValue = values[0];
 80	
 81	        for (int i = 1; i < values.length; i++) {
 82	            int value = values[i];
 83	            if (value < minValue) {
 84	                minValue = value;
 85	            }
 86	            if (value > maxValue) {
 87	                maxValue = value;
 88	            }
 89	        }
 90	
 91	        return new Range(minValue, maxValue);
 92	    }
 93	
 94	    private static void writeSortedValues(
 95	        int[] input,
 96	        int[] output,
 97	        CountingTable countingTable
 98	    ) {
 99	        for (int i = input.length - 1; i >= 0; i--) {
100	            int value = input[i];
101	            output[countingTable.outputIndex(value)] = value;
102	            countingTable.consume(value);
103	        }
104	    }
105	
106	    private record CountingTable(Range range, int[] prefixCounts) {
107	        private static CountingTable from(int[] values) {
108	            Range range = findRange(values);
109	            int[] prefixCounts = new int[range.size()];
110	
111	            for (int value : values) {
112	                prefixCounts[range.indexOf(value)]++;
113	            }
114	
115	            for (int i = 1; i < prefixCounts.length; i++) {
116	                prefixCounts[i] += prefixCounts[i - 1];
117	            }
118	
119	            return new CountingTable(range, prefixCounts);
120	        }
121	
122	        private int outputIndex(int value) {
123	            return prefixCounts[range.indexOf(value)] - 1;
124	        }
125	
126	        private void consume(int value) {
127	            prefixCounts[range.indexOf(value)]--;
128	        }
129	    }
130	
131	    private record Range(int minValue, int maxValue) {
132	        private int size() {
133	            long size = (long) maxValue - minValue + 1;
134	            if (size > Integer.MAX_VALUE) {
135	                throw new IllegalArgumentException(
136	                    "Counting sort range is too large to index."
137	                );
138	            }
139	
140	            return (int) size;
141	        }
142	
143	        private int indexOf(int value) {
144	            return value - minValue;
145	        }
146	    }
147	}
